// Bounding boxes in deck units: [x, y, width, height].
const MARK_BOX = [0.67, 44.32, 48.55, 48.55] as const;
const WORDMARK_BOX = [62.89, 32.64, 423.55, 70.59] as const;
const LOCKUP_BOX = [0.67, 32.64, 485.77, 70.59] as const;

export function LogoMark({
  size = 24,
  className,
}: {
  size?: number;
  className?: string;
}) {
  return (
    <svg
      width={size}
      height={size}
      viewBox={MARK_BOX.join(" ")}
      fill="currentColor"
      aria-hidden="true"
      className={className}
    >
      <path fillRule="evenodd" d={MARK_PATH} />
    </svg>
  );
}

/** The wordmark alone. `height` covers ascender to descender. */
export function LogoWordmark({
  height = 20,
  className,
}: {
  height?: number;
  className?: string;
}) {
  return (
    <svg
      width={(height * WORDMARK_BOX[2]) / WORDMARK_BOX[3]}
      height={height}
      viewBox={WORDMARK_BOX.join(" ")}
      fill="currentColor"
      aria-label="surfsync"
      role="img"
      className={className}
    >
      <path d={WORDMARK_PATH} />
    </svg>
  );
}

/** Horizontal lockup: mark + wordmark as set in the deck. `height` covers
 *  the "f" ascender to the "y" descender; the mark is ~0.69 of it. */
export function LogoLockup({
  height = 24,
  className,
}: {
  height?: number;
  className?: string;
}) {
  return (
    <svg
      width={(height * LOCKUP_BOX[2]) / LOCKUP_BOX[3]}
      height={height}
      viewBox={LOCKUP_BOX.join(" ")}
      fill="currentColor"
      aria-label="surfsync"
      role="img"
      className={className}
    >
      <path fillRule="evenodd" d={MARK_PATH} />
      <path d={WORDMARK_PATH} />
    </svg>
  );
}
